FROM zc_private.level_submission_contest c JOIN zc_private.level_submission_playlist_entry e ON e.id_playlist=c.current_playlist_id JOIN zc_private.level_submission_validation v ON v.id=e.id_validation AND v.valid JOIN zc_private.level_submissions s ON s.id=v.id_submission AND s.state='selected' JOIN public.level l ON l.xx_hash=s.level_hash LEFT JOIN LATERAL (SELECT name,image_url,author_id FROM public.level_item WHERE id_level=l.id AND workshop_id=s.workshop_id ORDER BY id DESC LIMIT 1) i ON true LEFT JOIN LATERAL (SELECT image_url FROM public.level_item WHERE id_level=l.id AND deleted=false AND image_url<>'' ORDER BY updated_at DESC,id DESC LIMIT 1) other_image ON true LEFT JOIN public.workshop_item wi ON wi.workshop_id=s.workshop_id LEFT JOIN public."user" u ON u.steam_id=i.author_id LEFT JOIN public.level_points p ON p.id_level=l.id WHERE c.id=$1
